"""launch_watch — 启动类动作的两个硬要求（用户口径）

1) **前提**：游戏类应用必须先把启动器拉起来（Steam / Battle.net）——应用条目里写
     "_require_process": "steam.exe", "_require_path": "D:\\steam\\Steam.exe",
     "_require_wait_s": 25
   进程不在就先起它，并等它出现（超过等待就明确报"前提没满足"）。
2) **验证**：Popen 返回 ≠ 真起来了（血债：Hearthstone Beta Launcher 单独跑只会挂着，
   游戏本体永远不出现，日志却写"✅ 已启动"）。条目里写
     "_watch": ["Hearthstone.exe"]
   拉起后轮询进程，出现才算成功；超时就报 ❌ + 手动地址。

配置：behavior.launch_verify_s（默认 15）｜behavior.launch_require_wait_s（默认 30）
"""
from __future__ import annotations

import os
import subprocess
import time

_LOCK_MARK = "__oc_launch_wrapped__"


def _log(msg, tag="ACT", level=None):
    try:
        from dlog import log
        log(msg, tag, level=level)
    except Exception:
        print(msg, flush=True)


def _tasklist():
    try:
        r = subprocess.run(["tasklist", "/NH", "/FO", "CSV"],
                           capture_output=True, text=True, timeout=20)
        out = r.stdout or ""
    except Exception:
        return set()
    names = set()
    for line in out.splitlines():
        line = line.strip()
        if not line or not line.startswith('"'):
            continue
        names.add(line.split('","')[0].strip('"').lower())
    return names


def running(name):
    return str(name or "").lower() in _tasklist()


def _app_entry(arg, cfg):
    """把 arg（应用名）解析成闭集条目（实体代理后的 cfg 里有 app_by_alias）"""
    try:
        from opencode_fastpath import intents as _intents
        c = _intents._entities_cfg(cfg)
    except Exception:
        c = cfg
    key = str(arg or "").strip().lower()
    try:
        e = (getattr(c, "app_by_alias", None) or {}).get(key)
        if e:
            return e
        for a in (getattr(c, "apps", None) or []):
            if str(a.get("name", "")).lower() == key:
                return a
    except Exception:
        pass
    return None


def ensure_required(entry, cfg):
    """→ (ok, 说明)。需要先起启动器就起，并等它出现。"""
    if not entry:
        return True, ""
    rp = entry.get("_require_path")
    rn = entry.get("_require_process")
    if not (rp and rn):
        return True, ""
    if running(rn):
        return True, f"{rn} 已在运行"
    if not os.path.exists(rp):
        return False, f"缺启动器：{rp} 不存在"
    wait_s = float((cfg.behavior or {}).get("launch_require_wait_s", 30) or 30)
    t0 = time.time()
    try:
        subprocess.Popen([rp], cwd=os.path.dirname(rp), close_fds=True)
    except Exception as e:
        return False, f"启动 {rn} 失败: {type(e).__name__}: {e}"
    while time.time() - t0 < wait_s:
        time.sleep(0.5)
        if running(rn):
            # ★ [OPENCODE-LR] 冷启动必须等启动器"真的能吃命令"
            #   血债（2026-10-19 实测）：Battle.net 进程 0.9s 就存在，但马上发
            #   `--exec=launch WTCG` 会被丢掉（转发进程 rc=0，本体永远不来）。
            #   实测：Battle.net【已经在运行】时同一命令 1s 就拉起 Hearthstone。
            warm = float((cfg.behavior or {}).get("launch_warmup_s", 6) or 6)
            _log(f"   ⏳ {rn} 已拉起（{time.time() - t0:.1f}s），"
                 f"等启动器就绪 {warm:.0f}s 再发命令", "ACT")
            time.sleep(warm)
            return True, f"已先拉起 {rn}（{time.time() - t0:.1f}s，含就绪等待）"
    return False, f"{rn} 起不来（{wait_s:.0f}s 内进程未出现）→ 请手动开一下"


def verify(entry, info, cfg):
    """→ (ok, 说明)：本体进程真的出现才算成功"""
    if not entry:
        return True, ""
    names = list(entry.get("_watch") or [])
    if not names:
        p = (info or {}).get("path") or entry.get("path")
        if p:
            names = [os.path.basename(str(p))]
    if not names:
        return True, ""
    wait_s = float((cfg.behavior or {}).get("launch_verify_s", 15) or 15)
    alive_s = float(entry.get("_watch_alive_s")
                    or (cfg.behavior or {}).get("launch_alive_s", 6) or 6)
    t0 = time.time()
    while time.time() - t0 < wait_s:
        for n in names:
            if running(n):
                # ★ 光"出现过"不算（血债：Hearthstone.exe 起来 1 秒就崩，却被判成功）
                #   出现后必须连续 alive_s 秒都还在
                seen = n
                t_seen = time.time()
                while time.time() - t_seen < alive_s:
                    time.sleep(0.5)
                    if not running(n):
                        return False, (f"{n} 起来 {time.time()-t_seen:.1f}s 又退了"
                                       f"（多半缺启动参数/需要客户端带上下文）")
                return True, f"本体进程 {n} 已出现并稳定存活 {alive_s:.0f}s"
        time.sleep(0.5)
    return False, (f"{wait_s:.0f}s 内没看到本体进程 {names} → 多半是被拦/启动器没就绪；"
                   f"手动试 {(info or {}).get('path') or entry.get('path')}")


def wrap_launch(fn):
    """包住 launch_app：① 先满足前提 ② 拉起后验证本体"""
    if getattr(fn, _LOCK_MARK, False):
        return fn

    def patched(arg, cfg=None, dry=False):
        entry = _app_entry(arg, cfg) if cfg is not None else None
        if dry or entry is None:
            return fn(arg, cfg, dry)
        ok_req, why_req = ensure_required(entry, cfg)
        if not ok_req:
            return False, f"前提没满足（{entry.get('name')}）：{why_req}", None
        if why_req:
            _log(f"   ⏳ {why_req}", "ACT")
        ok, msg, info = fn(arg, cfg, dry)
        if not ok:
            return ok, msg, info
        ok_ver, why_ver = verify(entry, info, cfg)
        if ok_ver:
            return True, f"{msg}｜{why_ver}", info
        # ★ [OPENCODE-LR] 启动器冷启动/更新中会吞掉第一条启动命令：
        #   进程 0.9s 就在 ≠ 能吃命令。这里按固定节奏重发，直到本体真的出现。
        #   实测：Battle.net 就绪后同一条 `--exec=launch WTCG` 1s 拉起 Hearthstone。
        if entry.get("_require_process"):
            beh = (cfg.behavior or {}) if cfg is not None else {}
            budget = float(beh.get("launch_retry_s", 45) or 45)
            gap = float(beh.get("launch_retry_gap_s", 5) or 5)
            t_end = time.time() + budget
            n = 0
            last = why_ver
            while time.time() < t_end:
                n += 1
                time.sleep(gap)
                _log(f"   ↻ 启动器可能还没就绪，重发启动命令（第 {n} 次）", "ACT")
                try:
                    ok2, msg2, info2 = fn(arg, cfg, dry)
                except Exception as e:
                    last = f"重发异常 {type(e).__name__}: {e}"
                    continue
                if not ok2:
                    last = msg2
                    continue
                ok_ver, why2 = verify(entry, info2, cfg)
                if ok_ver:
                    _log(f"   ✅ 重发 {n} 次后本体已起来", "ACT")
                    return True, f"{msg2}｜{why2}（冷启动重试 {n} 次）", info2
                last = why2
            return False, f"{msg} ✗ {last}（冷启动重试 {n} 次仍未起来）", info
        return False, f"{msg} ✗ {why_ver}", info

    patched.__name__ = getattr(fn, "__name__", "launch_app")
    setattr(patched, _LOCK_MARK, True)
    return patched
